import sys

def count_palindromic_cyclic_shifts(s):
    n = len(s)
    count = 0
    doubled_s = s + s
    for i in range(n):
        if doubled_s[i:i+n] == doubled_s[i:i+n][::-1]:
            count += 1
    return count

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    index = 1
    for _ in range(t):
        s = input[index]
        results.append(count_palindromic_cyclic_shifts(s))
        index += 1
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
